    from collections import deque
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            minr = min(y for y,x in cells); minc = min(x for y,x in cells)
            shape = frozenset((y-minr,x-minc) for y,x in cells)
            comps.append((color, shape, cells))
    # In both demonstrations, a component of color 2 has the same shape as
    # a component of color 5; recolor the 2 component to 5.
    shapes5 = {shape for color, shape, cells in comps if color == 5}
    for color, shape, cells in comps:
        if color == 2 and shape in shapes5:
            for r,c in cells: out[r][c] = 5
    return out

